include <robotics.scad>
// Origin: rear face center on floor; flange (mounting) face at z = L.
F = 42.3;     // frame square, max
L = 40;       // body length behind flange face
pilot_d = 22; pilot_h = 2.0;
pitch = 31;   // hole pattern
m3_d = 3.0;   hole_depth = 4.5; // M3 thread, min depth (modeled at nominal Ø)
$fn = 64;
difference() {
  union() {
    translate([-F/2, -F/2, 0]) cube([F, F, L]);
    translate([0, 0, L - 0.01]) cylinder(d = pilot_d, h = pilot_h + 0.01);
  }
  for (x = [-1, 1], y = [-1, 1])
    translate([x*pitch/2, y*pitch/2, L - hole_depth]) cylinder(d = m3_d, h = hole_depth + 0.1);
  // shaft bore through pilot (shaft is a separate body)
  translate([0, 0, L - 1]) cylinder(d = 5, h = pilot_h + 2);
}

// Origin at flange face; shaft starts 1 mm inside the bore and extends 24 mm above the flange face.
$fn = 48;
translate([0, 0, -1]) cylinder(d = 5, h = 24 + 1);
